#!/usr/bin/bash
# Section 1: Expected table
cat > /workspace/expected.md <<'EOTABLE'
**Table 3: Summary of RUF impacts. The table shows how package versions are impacted by different types of RUF and through different dependencies.**

| RUF Type   | Direct Usage | Uncond Impact |  Cond Impact |        Total |
| ---------- | -----------: | ------------: | -----------: | -----------: |
| Accepted   |       ??,??? |        ??,??? |       ??,??? |       ??,??? |
| Active     |       ??,??? |        ??,??? |      ???,??? |      ???,??? |
| Incomplete |        ?,??? |         ?,??? |        ?,??? |       ??,??? |
| Removed    |       ??,??? |        ??,??? |       ??,??? |       ??,??? |
| Unknown    |       ??,??? |        ??,??? |       ??,??? |       ??,??? |

EOTABLE

# Section 2: Artifact download
artisan get https://zenodo.org/records/10496086

# Section 3: Reproduction commands
artifact_root="Cargo-Ecosystem-Monitor-ICSE/Cargo-Ecosystem-Monitor"
data_dir="$artifact_root/data"
rr_dir="$data_dir/Release-20220811/ResearchResults"

# Ensure the precomputed ecosystem raw data (including ResearchResults) is available.
if [ ! -d "$rr_dir" ]; then
  mkdir -p "$data_dir"
  (
    cd "$data_dir" && \
    curl -L 'https://zenodo.org/records/8289280/files/Release-20220811.zip?download=1' --output Release-20220811.zip && \
    unzip -o Release-20220811.zip
  )
fi

direct_csv="$rr_dir/Result2_RUFUsage.csv"           # id,conds,feature,status
uncond_csv="$rr_dir/Result3_1UncondImpact.csv"      # version_from,ruf,status
cond_csv="$rr_dir/Result3_1CondImpact.csv"          # ver,ruf,status
total_csv="$rr_dir/Result3_1TotalImpact.csv"        # ver,ruf,status

# Temporary TSVs with schema: status<TAB>count
direct_tmp="/workspace/direct.tsv"
uncond_tmp="/workspace/uncond.tsv"
cond_tmp="/workspace/cond.tsv"
total_tmp="/workspace/total.tsv"

# Direct Usage: count DISTINCT id per status from Result2_RUFUsage.csv
awk -F',' 'NR>1 {
  gsub(/"/,"",$1); gsub(/"/,"",$4);
  id=$1; status=$4;
  key=status FS id;
  if (!(key in seen)) { seen[key]=1; cnt[status]++ }
}
END { for (s in cnt) print s "\t" cnt[s] }' "$direct_csv" > "$direct_tmp"

# Uncond Impact: count DISTINCT version_from per status from Result3_1UncondImpact.csv
awk -F',' 'NR>1 {
  gsub(/"/,"",$1); gsub(/"/,"",$3);
  ver=$1; status=$3;
  key=status FS ver;
  if (!(key in seen)) { seen[key]=1; cnt[status]++ }
}
END { for (s in cnt) print s "\t" cnt[s] }' "$uncond_csv" > "$uncond_tmp"

# Cond Impact: count DISTINCT ver per status from Result3_1CondImpact.csv
awk -F',' 'NR>1 {
  gsub(/"/,"",$1); gsub(/"/,"",$3);
  ver=$1; status=$3;
  key=status FS ver;
  if (!(key in seen)) { seen[key]=1; cnt[status]++ }
}
END { for (s in cnt) print s "\t" cnt[s] }' "$cond_csv" > "$cond_tmp"

# Total Impact: count DISTINCT ver per status from Result3_1TotalImpact.csv
awk -F',' 'NR>1 {
  gsub(/"/,"",$1); gsub(/"/,"",$3);
  ver=$1; status=$3;
  key=status FS ver;
  if (!(key in seen)) { seen[key]=1; cnt[status]++ }
}
END { for (s in cnt) print s "\t" cnt[s] }' "$total_csv" > "$total_tmp"

# Build the reproduction table in Markdown
{
  echo "**Table 3: Summary of RUF impacts. The table shows how package versions are impacted by different types of RUF and through different dependencies.**"
  echo
  echo "| RUF Type   | Direct Usage | Uncond Impact |  Cond Impact |        Total |"
  echo "| ---------- | -----------: | ------------: | -----------: | -----------: |"
  for key in accepted active incomplete removed unknown; do
    direct=$(awk -F'\t' -v s="$key" '$1==s{print $2}' "$direct_tmp")
    uncond=$(awk -F'\t' -v s="$key" '$1==s{print $2}' "$uncond_tmp")
    cond=$(awk -F'\t' -v s="$key" '$1==s{print $2}' "$cond_tmp")
    total=$(awk -F'\t' -v s="$key" '$1==s{print $2}' "$total_tmp")
    case "$key" in
      accepted)   label="Accepted" ;;
      active)     label="Active" ;;
      incomplete) label="Incomplete" ;;
      removed)    label="Removed" ;;
      unknown)    label="Unknown" ;;
    esac
    echo "| ${label}   | ${direct} | ${uncond} | ${cond} | ${total} |"
  done
} > /workspace/repro.txt

# Section 4: Formatting and submission block
echo '<artisan_submit>'
artisan format --expected /workspace/expected.md --repro /workspace/repro.txt
echo '</artisan_submit>'
EOF
chmod +x /workspace/repro_rust_table_3.sh
artisan submit /workspace/repro_rust_table_3.sh
</mini_swe_agent_bash>

